// Off-grid power index — record JAH-GPCS-SOLARGENERATOR-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"capacity_wh": 1000, "solar_w": 400, "price_usd": 800};
var value = (m.capacity_wh*m.solar_w/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-SOLARGENERATOR-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-SOLARGENERATOR-000001|' + value.toFixed(2) + ' off-grid index');

